// Portable counterpart of strings_G_T and strings_stringboxes (MATLAB).
export const keys=['Pmp','Voc','Isc','Vmp','Imp','alpha','beta','gamma'];
export const cellCounts=layout=>[36,42,48,54,60,66,72,78,84,90,96].map(n=>n*(layout==='half'?2:1));
export function cellSpec(d={},m={}){const inherited=d.layout==='catalog',layout=inherited?(m.layout??'half'):(d.layout??'half'),cellCount=inherited?(m.cellCount??(layout==='half'?108:54)):(d.cellCount??(layout==='half'?108:54));if(!['full','half'].includes(layout)||!cellCounts(layout).includes(cellCount))throw Error('Tipo o número de células no válido.');return {layout,cellCount,series:cellCount/(layout==='half'?2:1)};}
export const lin=(a,b,n)=>Array.from({length:n},(_,i)=>a+(b-a)*i/(n-1));
export const unique=a=>[...new Set(a)].sort((a,b)=>a-b);
const sum=a=>a.reduce((s,x)=>s+x,0), clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
export function checkModule(m){for(const k of ['Voc','Isc','Vmp','Imp','alpha','beta'])if(typeof m[k]!=='number'||!Number.isFinite(m[k]))throw Error(`Completa ${k} en el catálogo.`);if(!(m.Voc>m.Vmp&&m.Vmp>0&&m.Isc>m.Imp&&m.Imp>0))throw Error('Se requiere 0 < Vmp < Voc y 0 < Imp < Isc.');}
export function ends(isc,voc,a,rs,rsh){const i0=(isc+(isc*rs-voc)/rsh)/(Math.exp(voc/a)-Math.exp(isc*rs/a));return [i0*Math.expm1(voc/a)+voc/rsh,i0];}
const fits=new Map();
export function fitModule(m){checkModule(m);const key=JSON.stringify([m.Voc,m.Isc,m.Vmp,m.Imp]);if(fits.has(key))return fits.get(key);
  const loss=x=>{const [a,rs]=x.map(Math.exp);if(a<.2||a>5||rs>2)return 1e6+a*a+rs*rs;const [il,i0]=ends(m.Isc,m.Voc,a,rs,1000),u=m.Vmp+m.Imp*rs,d=i0/a*Math.exp(u/a)+.001;return ((il-i0*Math.expm1(u/a)-u/1000-m.Imp)/m.Isc)**2+((m.Imp-m.Vmp*d/(1+rs*d))/m.Isc)**2;};
  const x0=[Math.log(1.7),Math.log(.2)];let simplex=[x0,[x0[0]*1.05,x0[1]],[x0[0],x0[1]*1.05]].map(x=>({x,f:loss(x)}));
  const evalX=x=>({x,f:loss(x)}), mix=(a,b,t)=>a.map((v,i)=>v+t*(b[i]-v));
  for(let it=0;it<1400;it++){simplex.sort((a,b)=>a.f-b.f);let [best,mid,worst]=simplex;
    if(Math.max(...mid.x.map((v,i)=>Math.abs(v-best.x[i])),...worst.x.map((v,i)=>Math.abs(v-best.x[i])))<1e-10&&worst.f-best.f<1e-12)break;
    const center=mix(best.x,mid.x,.5),r=evalX(mix(center,worst.x,-1));
    if(r.f<best.f){const e=evalX(mix(center,r.x,2));simplex[2]=e.f<r.f?e:r;}
    else if(r.f<mid.f)simplex[2]=r;
    else{const outside=r.f<worst.f,c=evalX(mix(center,outside?r.x:worst.x,.5));if(c.f<(outside?r.f:worst.f))simplex[2]=c;else simplex=[best,evalX(mix(best.x,mid.x,.5)),evalX(mix(best.x,worst.x,.5))];}
  }simplex.sort((a,b)=>a.f-b.f);if(simplex[0].f>=1e-5)throw Error('Estos parámetros no se ajustan al modelo simplificado. Revisa la ficha.');const result=simplex[0].x.map(Math.exp);fits.set(key,result);return result;
}
export function interp(x,y,q,extrapolate=true){let n=x.length;if(n<2)return y[0]??0;let lo=0,hi=n-1;if(q<=x[0]){if(!extrapolate)return y[0];hi=1;}else if(q>=x[n-1]){if(!extrapolate)return y[n-1];lo=n-2;}else{while(hi-lo>1){let k=(hi+lo)>>1;if(x[k]<=q)lo=k;else hi=k;}}return y[lo]+(q-x[lo])/(x[hi]-x[lo])*(y[hi]-y[lo]);}
function pchip(x,y){const n=x.length,h=x.slice(1).map((v,i)=>v-x[i]),d=h.map((v,i)=>(y[i+1]-y[i])/v),s=Array(n).fill(0);
 for(let i=1;i<n-1;i++)if(d[i-1]*d[i]>0){let a=2*h[i]+h[i-1],b=h[i]+2*h[i-1];s[i]=(a+b)/(a/d[i-1]+b/d[i]);}
 const edge=(h0,h1,d0,d1)=>{let v=((2*h0+h1)*d0-h0*d1)/(h0+h1);return Math.sign(v)!==Math.sign(d0)?0:(Math.sign(d0)!==Math.sign(d1)&&Math.abs(v)>3*Math.abs(d0)?3*d0:v);};
 s[0]=edge(h[0],h[1],d[0],d[1]);s[n-1]=edge(h[n-2],h[n-3],d[n-2],d[n-3]);
 return q=>{let lo=0,hi=n-1;if(q<=x[0])return y[0];if(q>=x[hi])return y[hi];while(hi-lo>1){const k=(hi+lo)>>1;if(x[k]<=q)lo=k;else hi=k;}const t=(q-x[lo])/h[lo];return (2*t**3-3*t*t+1)*y[lo]+(t**3-2*t*t+t)*h[lo]*s[lo]+(-2*t**3+3*t*t)*y[hi]+(t**3-t*t)*h[lo]*s[hi];};
}
export function curve(V,I){const P=V.map((v,i)=>v*I[i]);let k=V.findIndex((v,i)=>v>=0&&I[i]>=0);if(k<0)k=0;for(let j=0;j<P.length;j++)if(V[j]>=0&&I[j]>=0&&P[j]>Math.max(0,P[k]))k=j;return {V,I,P,Pmp:Math.max(0,P[k]),Vmp:Math.max(0,V[k]),Imp:Math.max(0,I[k])};}
export function moduleCurve(m,T,G){checkModule(m);if(T< -15||T>85||G<0||G>1200||![T,G].every(Number.isFinite))throw Error('T debe estar entre −15 y 85 °C y G entre 0 y 1200 W/m².');const [a0,rs]=fitModule(m);if(G===0)return {...curve([0,0],[0,0]),Voc:0,Isc:0};const a=a0*(T+273.15)/298.15,rsh=1e6/G,isc=m.Isc*G/1000*(1+m.alpha*(T-25)),voc=Math.max(.001,m.Voc*(1+m.beta*(T-25))+a*Math.log(G/1000));if(isc<=0||1+m.beta*(T-25)<=0)throw Error('Coeficientes térmicos no físicos a esta temperatura.');const [il,i0]=ends(isc,voc,a,rs,rsh),u=lin(isc*rs,voc,1501),I=u.map(v=>Math.max(0,il-i0*Math.expm1(v/a)-v/rsh)),V=u.map((v,i)=>Math.max(0,v-I[i]*rs));I[0]=isc;I[I.length-1]=0;V[0]=0;V[V.length-1]=voc;return {...curve(V,I),Voc:voc,Isc:isc};}
export function randomFactors(N,si,sv,seed){let a=seed>>>0;const rand=()=>{a+=0x6D2B79F5;let t=a;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return ((t^t>>>14)>>>0)/4294967296;};const normal=()=>{let z;do{z=Math.sqrt(-2*Math.log(Math.max(1e-15,rand())))*Math.cos(2*Math.PI*rand());}while(Math.abs(z)>3);return z;};const z=[Array.from({length:40},normal),Array.from({length:40},normal)];return Array.from({length:N},(_,i)=>[1+z[0][i]*si/100,1+z[1][i]*sv/100]);}
export function simpleString(base,factors){if(base.Isc===0)return {...base,Voc:0,Isc:0};const inverse=pchip([...base.I].reverse(),[...base.V].reverse()),current=unique([...lin(0,base.Isc*Math.max(...factors.map(f=>f[0])),2501),...factors.flatMap(f=>[base.Imp*f[0],base.Isc*f[0]])]);const V=[],I=[];for(const i of current){let v=0;for(const [fi,fv]of factors){const q=i/fi;v+=q>base.Isc?-Math.min(1.5,100*(q-base.Isc)):inverse(q)*fv;}if(v>=0){V.push(v);I.push(i);}}return {...curve(V,I),Voc:V[0],Isc:I[I.length-1]};}
export function irradianceGrid(){return unique([...lin(0,20,21),25,30,35,40,45,50,...Array.from({length:57},(_,i)=>70+i*20),1000,1200]);}
export function moduleAnalysis(m,p){const factors=randomFactors(p.N,p.dispersion?p.sigmaI:0,p.dispersion?p.sigmaV:0,p.seed),base=moduleCurve(m,p.T,p.G),nominal=Array.from({length:p.N},()=>[1,1]);const actual=simpleString(base,factors),uniform=simpleString(base,nominal),stc=simpleString(moduleCurve(m,25,1000),nominal),independent=base.Pmp*sum(factors.map(([i,v])=>i*v));const G=unique([...irradianceGrid(),p.G]),vg={G,mp:[],oc:[],refmp:[],refoc:[]};for(const g of G){const c=simpleString(moduleCurve(m,p.T,g),factors),r=simpleString(moduleCurve(m,25,g),nominal);vg.mp.push(c.Vmp);vg.oc.push(c.Voc);vg.refmp.push(r.Vmp);vg.refoc.push(r.Voc);}return {base,actual,uniform,stc,factors,independent,loss:independent?100*(1-actual.Pmp/independent):0,vg};}

export const sections=[4,6,10,16,25,35,50,70,95,120,150,185,240];
export function cableR(length,section,T){const index=sections.indexOf(section);if(index<0||length<0||!Number.isFinite(length)||T< -20||T>120||!Number.isFinite(T))throw Error('Cable no válido.');return 2*length/1000*[5.09,3.39,1.95,1.24,.795,.565,.393,.277,.210,.164,.132,.108,.0817][index]*(1+.00393*(T-20));}
function sortedCurve(V,I){const pts=V.map((v,i)=>[v,I[i]]).sort((a,b)=>a[0]-b[0]),v=[],i=[];for(const p of pts)if(p[0]!==v.at(-1)){v.push(p[0]);i.push(p[1]);}let voc=0;for(let k=1;k<i.length;k++)if(i[k]<=0&&i[k-1]>0)voc=v[k-1]+(v[k]-v[k-1])*i[k-1]/(i[k-1]-i[k]);return {...curve(v,i),Voc:Math.max(0,voc),Isc:interp(v,i,0)};}
const logspace=(a,b,n)=>lin(a,b,n).map(x=>10**x);
function clipPolygon(poly,n,c){let out=[],prev=poly.at(-1);if(!prev)return out;let dp=prev[0]*n[0]+prev[1]*n[1]-c;for(const next of poly){let dn=next[0]*n[0]+next[1]*n[1]-c;if((dp<=0)!==(dn<=0)){const t=dp/(dp-dn);out.push([prev[0]+t*(next[0]-prev[0]),prev[1]+t*(next[1]-prev[1])]);}if(dn<=0)out.push(next);prev=next;dp=dn;}return out;}
export function geometry(d,m){const spec=cellSpec(d,m),half=spec.layout==='half',rows=spec.cellCount/6,cells=[];const [sx,sy,sw,sh]=d.shadow;for(let col=0;col<6;col++)for(let row=0;row<rows;row++){let x=col/6,y=row/rows,w=1/6,h=1/rows;if(d.rotation===90)[x,y,w,h]=[1-y-h,x,h,w];let area=Math.max(0,Math.min(x+w,sx+sw)-Math.max(x,sx))*Math.max(0,Math.min(y+h,sy+sh)-Math.max(y,sy));if(d.shape==='triangle'&&sw>0&&sh>0){let p=[[x,y],[x+w,y],[x+w,y+h],[x,y+h]];p=clipPolygon(p,[-1,0],-sx);p=clipPolygon(p,[0,-1],-sy);p=clipPolygon(p,[1/sw,1/sh],1+sx/sw+sy/sh);area=Math.abs(sum(p.map((a,i)=>a[0]*p[(i+1)%p.length][1]-a[1]*p[(i+1)%p.length][0])))/2;}cells.push({x,y,w,h,group:Math.floor(col/2),branch:half?Math.floor(row/(rows/2)):0,coverage:clamp(area/(w*h),0,1)});}return {cells,parallel:half?2:1,area:half?.5:1,series:spec.series};}
export function poa(env,beta,az){const rad=Math.PI/180,sd=x=>Math.sin(x*rad),cd=x=>Math.cos(x*rad);if(env.altitude<=0)return 0;const cos=sd(env.altitude)*cd(beta)+cd(env.altitude)*sd(beta)*cd(env.azimuth-az);return Math.min(1200,env.dni*Math.max(0,cos)+env.dhi*(1+cd(beta))/2+env.albedo*(env.dni*sd(env.altitude)+env.dhi)*(1-cd(beta))/2);}
export function moduleIrradiance(s,d,j,env){if(s.mode==='soft')return poa(env,s.tilt+s.amplitude*Math.sin(2*Math.PI*j/s.period+s.phase*Math.PI/180),s.azimuth);if(s.mode==='roof')return env.roofMethod==='fixed'?env['g'+d.roof]:poa(env,env['tilt'+d.roof],env['az'+d.roof]);return d.G;}
const cellCache=new Map();
export function fieldModule(m,d){const key=JSON.stringify([m,d]);if(cellCache.has(key))return cellCache.get(key);const geom=geometry(d,m),[a0,rs0]=fitModule(m),a=a0*(d.T+273.15)/298.15/geom.series,rs=rs0/geom.series/geom.area,rsh=1000/geom.series/geom.area,isc0=m.Isc*geom.area*(1+m.alpha*(d.T-25)),voc0=m.Voc/geom.series*(1+m.beta*(d.T-25));const cells=geom.cells.map(c=>{const G=d.G*(1-c.coverage*(1-d.transmission)),isc=isc0*G/1000*d.fI;let rh,il,i0;if(isc>0){rh=rsh*1000/G;const voc=Math.max(.001,voc0+a*Math.log(G/1000*d.fI));[il,i0]=ends(isc,voc,a,rs,rh);}else{rh=rsh*1e6;il=0;[,i0]=ends(isc0,voc0,a,rs,rsh);}return {...c,G,isc,rh,il,i0};});
 const imax=isc0*Math.max(1,...cells.map(c=>c.G/1000*d.fI))*1.12,ib=unique([...logspace(Math.log10(Math.max(.01,2*imax)),5,180).map(x=>-x),...lin(-2*imax,imax,1801),0,...cells.map(c=>c.isc)]);
 const groups=[];for(let g=0;g<3;g++){const branch=[];for(let b=0;b<geom.parallel;b++){const ids=cells.filter(c=>c.group===g&&c.branch===b),v=ib.map(q=>{let total=0;for(const c of ids){if(q>c.isc){total-=10/geom.area*(q-c.isc);continue;}const target=c.il-q;let u=a*Math.log1p(Math.max(0,target)/c.i0);for(let k=0;k<9;k++){const e=Math.exp(u/a);u-=(c.i0*(e-1)+u/c.rh-target)/(c.i0/a*e+1/c.rh);}total+=u-q*rs;}return total;});branch.push({V:v.slice().reverse(),I:ib.slice().reverse()});}
 const vg=unique([...lin(-2,Math.max(...branch.map(b=>b.V.at(-1))),1801),...branch.flatMap(b=>b.V.filter(v=>v>=-2))]),ig=vg.map(v=>sum(branch.map(b=>interp(b.V,b.I,v))));groups.push({I:ig.reverse(),V:vg.reverse()});}
 const I=unique([...logspace(-3,5,260).map(x=>-x),...lin(-2*geom.parallel*imax,0,401),...lin(0,geom.parallel*imax,2401)]),groupV=groups.map(g=>I.map(q=>Math.max(-.5,d.fV*interp(g.I,g.V,q)))),V=I.map((_,i)=>sum(groupV.map(v=>v[i]))),c=curve(V,I);const result={...c,I,V,groupV,cells,geom,Voc:interp(I,V,0)};cellCache.set(key,result);if(cellCache.size>200)cellCache.delete(cellCache.keys().next().value);return result;
}
function parallel(curves,R,vmax){const V=unique([...lin(0,Math.max(1,vmax),3001),...curves.flatMap(c=>[c.Vmp,c.Voc])]),I=V.map(v=>sum(curves.map(c=>{const i=interp(c.V,c.I,v);return c.block?Math.max(0,i):i;})));return sortedCurve(V.map((v,k)=>v-I[k]*R),I);}
export function fieldAnalysis(m,config){checkModule(m);const active=config.strings.map((s,i)=>s.active?i:-1).filter(i=>i>=0);if(!active.length)throw Error('Activa al menos un string.');let vmax=1;const strings=config.strings.map(()=>null);for(const idx of active){const s=config.strings[idx],f=randomFactors(s.modules.length,s.sigmaI,s.sigmaV,s.seed);const modules=s.modules.map((d,j)=>fieldModule(m,{...d,G:moduleIrradiance(s,d,j,config.env),fI:d.fI*f[j][0],fV:d.fV*f[j][1]}));const imax=Math.max(...modules.map(m=>m.I.at(-1))),I=unique([...logspace(Math.log10(Math.max(.01,2*imax)),5,160).map(x=>-x),...lin(-2*imax,0,401),...lin(0,imax,5001),...modules.map(m=>m.Imp)]),V=I.map(i=>sum(modules.map(m=>interp(m.I,m.V,i)))),R=cableR(s.length,s.section,s.cableT),source=sortedCurve(V,I),wire=sortedCurve(V.map((v,j)=>v-I[j]*R),I);wire.block=config.blocking;strings[idx]={modules,source,wire,R,modulePower:sum(modules.map(m=>m.Pmp))};vmax=Math.max(vmax,source.Voc);}
 const boxes=config.boxes.map((b,j)=>{const ids=active.filter(i=>config.strings[i].box===j);if(!ids.length)return null;const curves=ids.map(i=>strings[i].wire),R=cableR(b.length,b.section,b.cableT);return {ids,R,before:parallel(curves,0,vmax),after:parallel(curves,R,vmax)};});const used=boxes.filter(Boolean),network=parallel(used.map(b=>b.after),0,vmax),stages=[sum(active.map(i=>strings[i].modulePower)),sum(active.map(i=>strings[i].source.Pmp)),sum(active.map(i=>strings[i].wire.Pmp)),sum(used.map(b=>b.before.Pmp)),sum(used.map(b=>b.after.Pmp)),network.Pmp];const result={strings,boxes,network,stages,vmax,config};result.op=fieldOperation(result,network.Vmp);return result;}
export function fieldOperation(r,v){let sourcePower=0,wireLoss=0,current=0;const strings=Array(r.strings.length).fill(null),boxes=r.boxes.map((b,idx)=>{if(!b)return null;const i=interp(b.after.V,b.after.I,v),internal=v+i*b.R;current+=i;wireLoss+=i*i*b.R;for(const k of b.ids){const s=r.strings[k];let si=interp(s.wire.V,s.wire.I,internal);if(r.config.blocking)si=Math.max(0,si);const voltages=s.modules.map(m=>sum(m.groupV.map(g=>Math.max(-.5,interp(m.I,g,si))))),sv=sum(voltages),loss=si*si*s.R;sourcePower+=sv*si;wireLoss+=loss;strings[k]={I:si,V:sv,P:sv*si,loss,drop:si*s.R,moduleV:voltages,bypass:s.modules.map(m=>m.groupV.filter(g=>interp(m.I,g,si)<=-.5+1e-6).length)};}return {I:i,V:internal,loss:i*i*b.R};});return {V:v,I:current,P:v*current,sourcePower,wireLoss,residual:sourcePower-wireLoss-v*current,strings,boxes};}
export function newModule(){return {layout:'catalog',T:25,G:1000,fI:1,fV:1,shadow:[0,0,0,0],shape:'rectangle',transmission:.1,rotation:0,roof:'A'};}
export function newString(j=0){return {name:`String ${j+1}`,active:true,compare:true,box:0,modules:Array.from({length:10},newModule),length:20*(j+1),section:6,cableT:40,sigmaI:0,sigmaV:0,seed:j+1,mode:'manual',tilt:25,azimuth:180,amplitude:5,period:8,phase:0};}
export function newField(){return {strings:[0,1,2].map(newString),boxes:[{name:'Stringbox 1',length:50,section:16,cableT:40}],blocking:false,env:{altitude:35,azimuth:120,dni:800,dhi:120,albedo:.2,roofMethod:'solar',tiltA:25,azA:90,gA:900,tiltB:25,azB:270,gB:500}};}
